        user = self.require_user()
        if user.get("role") not in {"faculty", "media_lab", "admin", "staff"} or not str(user.get("email", "")).endswith("@krea.edu.in"):
            raise ApiError("Staff access is required", 403)
        return user

    def require_admin(self):
